mapper.select:
select a.id, a.title, u.username as author, a.category_id, a.create_at, a.update_at, c.name as category
from article a left join user u on a.user_id = u.id left join category c on a.category_id = c.id


        a.user_id = #{userId}


        and a.title like CONCAT('%', #{queryParam.keyword}, '%')


        and a.category_id = #{queryParam.categoryId}
